import { ChangeDetectionStrategy, Component, computed, ElementRef, inject, ViewEncapsulation } from '@angular/core';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind, BindModule } from 'primeng/bind';
import type { ScrollArea } from './scrollarea';
import { SCROLLAREA_INSTANCE, SCROLLAREA_VIEWPORT_INSTANCE } from './scrollarea-token';
import { ScrollAreaStyle } from './style/scrollareastyle';

/**
 * ScrollAreaViewport is a helper component for ScrollArea component.
 * @group Components
 */
@Component({
    selector: 'p-scrollarea-viewport, p-scroll-area-viewport',
    standalone: true,
    imports: [BindModule],
    template: `<ng-content></ng-content>`,
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    providers: [
        { provide: SCROLLAREA_VIEWPORT_INSTANCE, useExisting: ScrollAreaViewport },
        { provide: PARENT_INSTANCE, useExisting: ScrollAreaViewport }
    ],
    host: {
        '[class]': 'cx("viewport")',
        '[style]': 'sx("viewport")',
        '[attr.tabindex]': 'viewportTabindex()',
        '[attr.data-scroll-y-before]': 'dataScrollYBefore()',
        '[attr.data-scroll-y-after]': 'dataScrollYAfter()',
        '[attr.data-scroll-x-before]': 'dataScrollXBefore()',
        '[attr.data-scroll-x-after]': 'dataScrollXAfter()',
        '(scroll)': 'pcScrollArea.onScroll()'
    },
    hostDirectives: [Bind]
})
export class ScrollAreaViewport extends BaseComponent {
    componentName = 'ScrollAreaViewport';

    $pcScrollAreaViewport: ScrollAreaViewport | undefined = inject(SCROLLAREA_VIEWPORT_INSTANCE, { optional: true, skipSelf: true }) ?? undefined;

    bindDirectiveInstance = inject(Bind, { self: true });

    pcScrollArea = inject<ScrollArea>(SCROLLAREA_INSTANCE);

    _componentStyle = inject(ScrollAreaStyle);

    private hostEl = inject(ElementRef);

    viewportTabindex = computed(() => (this.pcScrollArea.hasOverflowX() || this.pcScrollArea.hasOverflowY() ? this.pcScrollArea.tabindex() : null));

    dataScrollYBefore = computed(() => (this.pcScrollArea.yBefore() ? '' : null));

    dataScrollYAfter = computed(() => (this.pcScrollArea.yAfter() ? '' : null));

    dataScrollXBefore = computed(() => (this.pcScrollArea.xBefore() ? '' : null));

    dataScrollXAfter = computed(() => (this.pcScrollArea.xAfter() ? '' : null));

    onAfterViewChecked(): void {
        this.bindDirectiveInstance.setAttrs(this.pcScrollArea.ptms(['viewport']));
    }

    onAfterViewInit() {
        this.pcScrollArea.viewportEl = this.hostEl.nativeElement;
    }
}
