import { ChangeDetectionStrategy, Component, computed, ElementRef, inject, ViewEncapsulation } from '@angular/core';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind, BindModule } from 'primeng/bind';
import type { ScrollArea } from './scrollarea';
import { SCROLLAREA_INSTANCE } from './scrollarea-token';
import { ScrollAreaStyle } from './style/scrollareastyle';

/**
 * ScrollAreaCorner is a helper component for ScrollArea component.
 * @group Components
 */
@Component({
    selector: 'p-scrollarea-corner, p-scroll-area-corner',
    standalone: true,
    imports: [BindModule],
    template: ``,
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    providers: [{ provide: PARENT_INSTANCE, useExisting: ScrollAreaCorner }],
    host: {
        '[class]': 'cx("corner")',
        '[style]': 'sx("corner")'
    },
    hostDirectives: [Bind]
})
export class ScrollAreaCorner extends BaseComponent {
    componentName = 'ScrollAreaCorner';

    bindDirectiveInstance = inject(Bind, { self: true });

    pcScrollArea = inject<ScrollArea>(SCROLLAREA_INSTANCE);

    _componentStyle = inject(ScrollAreaStyle);

    private hostEl = inject(ElementRef);

    isHidden = computed(() => this.pcScrollArea.cornerHidden());

    onAfterViewChecked(): void {
        this.bindDirectiveInstance.setAttrs(this.pcScrollArea.ptms(['corner']));
    }

    onAfterViewInit() {
        this.pcScrollArea.cornerEl = this.hostEl.nativeElement;
    }
}
